unsigned Hashtable::gethashcode(const char *s,size_t sz)
{
    // SDI R2600 .bin indexes persist this legacy hash. The mirror's APHash
    // experiment retained VER_INDEX=0x205, silently breaking existing indexes.
    // Unsigned arithmetic gives the required defined 32-bit wraparound.
    unsigned h=5381u;
    while(sz--)h=(h*33u)^static_cast<int>(static_cast<signed char>(*s++));
    return h;
}

