void Driverpack::saveindex()
{
    wchar_t filename[BUFLEN];
    FILE *f;
    size_t sz;
    int version=VER_INDEX;
    char *mem,*p,*mem_pack;

    getindexfilename(col->getIndex_bin_dir(),L"bin",filename);
    std::wstring pending=std::wstring(filename)+L".partial";
    if(!System.canWriteFile(pending.c_str(),L"wb"))
    {
        Log.print_err("ERROR in driverpack_saveindex(): Write-protected,'%S'\n",filename);
        return;
    }
    f=_wfopen(pending.c_str(),L"wb");
    if(!f)return;
    bool complete=true;

    // calculate size of all data
    sz=
        inffile.size()*sizeof(data_inffile_t)+
        manufacturer_list.size()*sizeof(data_manufacturer_t)+
        desc_list.size()*sizeof(data_desc_t)+
        HWID_list.size()*sizeof(data_HWID_t)+
        text_ind.getSize()+
        indexes.getSize()*sizeof(Hashitem)+sizeof(int)+
        6*sizeof(int)*2;

    // construct a buffer in memory of the entire index
    p=mem=new char[sz];
    fwrite("SDW",3,1,f);
    fwrite(&version,sizeof(int),1,f);

    p=inffile.savedata(p);
    p=manufacturer_list.savedata(p);
    p=desc_list.savedata(p);
    p=HWID_list.savedata(p);
    p=text_ind.savedata(p);
    p=indexes.savedata(p);

    // compress the output and write
    if(Settings.flags&COLLECTION_USE_LZMA)
    {
        mem_pack=new char[sz];
        sz=encode(mem_pack,sz,mem,sz);
        complete=sz && fwrite(mem_pack,sz,1,f)==1;
        delete[] mem_pack;
    }
    else complete=fwrite(mem,sz,1,f)==1;

    delete[] mem;
    complete=fclose(f)==0 && complete;
    if(!complete || !MoveFileExW(pending.c_str(),filename,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){DeleteFileW(pending.c_str());Log.print_err("Index write failed; previous cache preserved.\n");return;}
    type=DRIVERPACK_TYPE_INDEXED;
}
